app.get("/parley.js", serveStatic({ path: process.env.FULLSTACK_043_BROWSER ?? "./dist/logic.js" }));
app.get("/*", serveStatic({ root: "./public" }));
serve({ fetch: app.fetch, hostname: "127.0.0.1", port: Number(process.env.PARLEY_WEB_PORT) });

