use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub scout_drones: i64,
    pub cargo_drones: i64,
    pub launch_pads: i64,
    pub night_mission: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.scout_drones >= 0 && self.cargo_drones >= 0 && self.launch_pads >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub drone_total: i64,
    pub scout_flight_minutes: i64,
    pub cargo_flight_minutes: i64,
    pub night_setup_minutes: i64,
    pub mission_load_minutes: i64,
    pub launch_capacity_minutes: i64,
    pub completed_flight_minutes: i64,
    pub delayed_flight_minutes: i64,
    pub flight_waves: i64,
    pub wildfire_score: i64,
    pub wildfire_mode: String,
}

pub fn score(scout_drones: i64, cargo_drones: i64, launch_pads: i64, night_mission: bool) -> i64 {
    let scout_flight_minutes = scout_drones * 13;
    let cargo_flight_minutes = cargo_drones * 21;
    let night_setup_minutes = if night_mission { launch_pads * 8 } else { 0 };
    let mission_load_minutes = scout_flight_minutes + cargo_flight_minutes + night_setup_minutes;
    let launch_capacity_minutes = launch_pads * 50;
    let completed_flight_minutes = mission_load_minutes.min(launch_capacity_minutes);
    let delayed_flight_minutes = (mission_load_minutes - launch_capacity_minutes).max(0);
    let flight_waves = mission_load_minutes / 40;

    completed_flight_minutes + delayed_flight_minutes * 6 + flight_waves * 9
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let scout_flight_minutes = v.scout_drones * 13;
    let cargo_flight_minutes = v.cargo_drones * 21;
    let night_setup_minutes = if v.night_mission { v.launch_pads * 8 } else { 0 };
    let mission_load_minutes = scout_flight_minutes + cargo_flight_minutes + night_setup_minutes;
    let launch_capacity_minutes = v.launch_pads * 50;
    let delayed_flight_minutes = (mission_load_minutes - launch_capacity_minutes).max(0);

    ResponseOutput {
        drone_total: v.scout_drones + v.cargo_drones,
        scout_flight_minutes,
        cargo_flight_minutes,
        night_setup_minutes,
        mission_load_minutes,
        launch_capacity_minutes,
        completed_flight_minutes: mission_load_minutes.min(launch_capacity_minutes),
        delayed_flight_minutes,
        flight_waves: mission_load_minutes / 40,
        wildfire_score: score(v.scout_drones, v.cargo_drones, v.launch_pads, v.night_mission),
        wildfire_mode: if delayed_flight_minutes == 0 {
            "ready"
        } else if v.night_mission {
            "night_delay"
        } else {
            "day_delay"
        }
        .into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_wildfire_mission_score(a: i64, b: i64, c: i64, d: i32) -> i64 {
    score(a, b, c, d != 0)
}

