const satelliteUplinkScore=(sciencePackets,navigationPackets,groundAntennas,solarInterference)=>{
  const transmitSeconds=sciencePackets*6+navigationPackets*10+(solarInterference?groundAntennas*7:0);
  const capacitySeconds=groundAntennas*44;
  const sentSeconds=Math.min(transmitSeconds,capacitySeconds);
  const queuedSeconds=Math.max(transmitSeconds-capacitySeconds,0);
  const transmissionWindows=Math.floor(transmitSeconds/25);
  return sentSeconds+queuedSeconds*7+transmissionWindows*12;
};
export async function loadParley() { return { satellite_uplink_score: satelliteUplinkScore }; }

