export type RequestInput = {
  passenger_groups: number;
  supply_crates: number;
  gondola_cabins: number;
  express_service: boolean;
};

export const margin = (passengerGroups: number, supplyCrates: number, cabins: number, express: boolean) => {
  const required = passengerGroups * 8 + supplyCrates * 13 + (express ? cabins * 5 : 0);
  const capacity = cabins * 42;
  const carried = Math.min(required, capacity);
  return Math.max(capacity - carried, 0);
};

export const handle = (value: RequestInput) => {
  const riderLoadUnits = value.passenger_groups * 8;
  const freightLoadUnits = value.supply_crates * 13;
  const expressLoadUnits = value.express_service ? value.gondola_cabins * 5 : 0;
  const gondolaRequiredUnits = riderLoadUnits + freightLoadUnits + expressLoadUnits;
  const gondolaCapacityUnits = value.gondola_cabins * 42;
  const carriedLoadUnits = Math.min(gondolaRequiredUnits, gondolaCapacityUnits);
  const strandedLoadUnits = Math.max(gondolaRequiredUnits - gondolaCapacityUnits, 0);

  return {
    gondola_item_total: value.passenger_groups + value.supply_crates,
    rider_load_units: riderLoadUnits,
    freight_load_units: freightLoadUnits,
    express_load_units: expressLoadUnits,
    gondola_required_units: gondolaRequiredUnits,
    gondola_capacity_units: gondolaCapacityUnits,
    carried_load_units: carriedLoadUnits,
    stranded_load_units: strandedLoadUnits,
    lift_margin_units: Math.max(gondolaCapacityUnits - carriedLoadUnits, 0),
    gondola_condition: strandedLoadUnits === 0 ? "clear" : value.express_service ? "express_stranded" : "standard_stranded",
  };
};

export async function loadParley() {
  return {
    gondola_lift_margin: (passengerGroups: number, supplyCrates: number, cabins: number, express: boolean) =>
      BigInt(margin(passengerGroups, supplyCrates, cabins, express)),
  };
}

