const satelliteUplinkScore = (sciencePackets, navigationPackets, groundAntennas, solarInterference) => {
  const scienceSeconds = BigInt(sciencePackets) * 6n;
  const navigationSeconds = BigInt(navigationPackets) * 10n;
  const antennas = BigInt(groundAntennas);
  const interferenceSeconds = solarInterference ? antennas * 7n : 0n;
  const transmitSeconds = scienceSeconds + navigationSeconds + interferenceSeconds;
  const capacitySeconds = antennas * 44n;
  const sentSeconds = transmitSeconds < capacitySeconds ? transmitSeconds : capacitySeconds;
  const queuedSeconds = transmitSeconds > capacitySeconds ? transmitSeconds - capacitySeconds : 0n;
  const transmissionWindows = transmitSeconds / 25n;
  return sentSeconds + queuedSeconds * 7n + transmissionWindows * 12n;
};
export async function loadParley() { return { satellite_uplink_score: satelliteUplinkScore }; }

