use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub science_packets: i64,
    pub navigation_packets: i64,
    pub ground_antennas: i64,
    pub solar_interference: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.science_packets >= 0
            && self.navigation_packets >= 0
            && self.ground_antennas >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub uplink_packet_total: i64,
    pub science_transmit_seconds: i64,
    pub navigation_transmit_seconds: i64,
    pub interference_seconds: i64,
    pub transmit_seconds: i64,
    pub antenna_capacity_seconds: i64,
    pub sent_seconds: i64,
    pub queued_seconds: i64,
    pub transmission_windows: i64,
    pub uplink_score: i64,
    pub uplink_mode: String,
}

pub fn score(
    science_packets: i64,
    navigation_packets: i64,
    ground_antennas: i64,
    solar_interference: bool,
) -> i64 {
    let science_transmit_seconds = science_packets * 6;
    let navigation_transmit_seconds = navigation_packets * 10;
    let interference_seconds = if solar_interference {
        ground_antennas * 7
    } else {
        0
    };
    let transmit_seconds =
        science_transmit_seconds + navigation_transmit_seconds + interference_seconds;
    let antenna_capacity_seconds = ground_antennas * 44;
    let sent_seconds = transmit_seconds.min(antenna_capacity_seconds);
    let queued_seconds = (transmit_seconds - antenna_capacity_seconds).max(0);
    let transmission_windows = transmit_seconds / 25;

    sent_seconds + queued_seconds * 7 + transmission_windows * 12
}

pub fn handle(input: RequestInput) -> ResponseOutput {
    let science_transmit_seconds = input.science_packets * 6;
    let navigation_transmit_seconds = input.navigation_packets * 10;
    let interference_seconds = if input.solar_interference {
        input.ground_antennas * 7
    } else {
        0
    };
    let transmit_seconds =
        science_transmit_seconds + navigation_transmit_seconds + interference_seconds;
    let antenna_capacity_seconds = input.ground_antennas * 44;
    let sent_seconds = transmit_seconds.min(antenna_capacity_seconds);
    let queued_seconds = (transmit_seconds - antenna_capacity_seconds).max(0);
    let transmission_windows = transmit_seconds / 25;
    let uplink_score =
        sent_seconds + queued_seconds * 7 + transmission_windows * 12;
    let uplink_mode = if queued_seconds == 0 {
        "synchronized"
    } else if input.solar_interference {
        "solar_queue"
    } else {
        "routine_queue"
    };

    ResponseOutput {
        uplink_packet_total: input.science_packets + input.navigation_packets,
        science_transmit_seconds,
        navigation_transmit_seconds,
        interference_seconds,
        transmit_seconds,
        antenna_capacity_seconds,
        sent_seconds,
        queued_seconds,
        transmission_windows,
        uplink_score,
        uplink_mode: uplink_mode.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_satellite_uplink_score(
    science_packets: i64,
    navigation_packets: i64,
    ground_antennas: i64,
    solar_interference: i32,
) -> i64 {
    score(
        science_packets,
        navigation_packets,
        ground_antennas,
        solar_interference != 0,
    )
}

