const wildfireMissionScore = (scoutDrones, cargoDrones, launchPads, nightMission) => {
  const missionLoad =
    scoutDrones * 13 +
    cargoDrones * 21 +
    (nightMission ? launchPads * 8 : 0);
  const launchCapacity = launchPads * 50;
  const completed = Math.min(missionLoad, launchCapacity);
  const delayed = Math.max(missionLoad - launchCapacity, 0);
  const flightWaves = Math.floor(missionLoad / 40);
  return completed + delayed * 6 + flightWaves * 9;
};

export async function loadParley() { return { wildfire_mission_score: wildfireMissionScore }; }

