const wildfireMissionScore = (scoutDrones, cargoDrones, launchPads, nightMission) => {
  const scouts = BigInt(scoutDrones);
  const cargo = BigInt(cargoDrones);
  const pads = BigInt(launchPads);
  const load = scouts * 13n + cargo * 21n + (nightMission ? pads * 8n : 0n);
  const capacity = pads * 50n;
  const delayed = load > capacity ? load - capacity : 0n;
  const completed = load < capacity ? load : capacity;
  return completed + delayed * 6n + (load / 40n) * 9n;
};
export async function loadParley() { return { wildfire_mission_score: wildfireMissionScore }; }

