use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub science_packets: i64,
    pub navigation_packets: i64,
    pub ground_antennas: i64,
    pub solar_interference: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.science_packets >= 0 && self.navigation_packets >= 0 && self.ground_antennas >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub uplink_packet_total: i64,
    pub science_transmit_seconds: i64,
    pub navigation_transmit_seconds: i64,
    pub interference_seconds: i64,
    pub transmit_seconds: i64,
    pub antenna_capacity_seconds: i64,
    pub sent_seconds: i64,
    pub queued_seconds: i64,
    pub transmission_windows: i64,
    pub uplink_score: i64,
    pub uplink_mode: String,
}

pub fn score(science_packets: i64, navigation_packets: i64, ground_antennas: i64, solar_interference: bool) -> i64 {
    let science_transmit_seconds = science_packets * 6;
    let navigation_transmit_seconds = navigation_packets * 10;
    let interference_seconds = if solar_interference { ground_antennas * 7 } else { 0 };
    let transmit_seconds = science_transmit_seconds + navigation_transmit_seconds + interference_seconds;
    let antenna_capacity_seconds = ground_antennas * 44;
    let sent_seconds = transmit_seconds.min(antenna_capacity_seconds);
    let queued_seconds = (transmit_seconds - antenna_capacity_seconds).max(0);
    let transmission_windows = transmit_seconds / 25;
    sent_seconds + queued_seconds * 7 + transmission_windows * 12
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let science_transmit_seconds = v.science_packets * 6;
    let navigation_transmit_seconds = v.navigation_packets * 10;
    let interference_seconds = if v.solar_interference { v.ground_antennas * 7 } else { 0 };
    let transmit_seconds = science_transmit_seconds + navigation_transmit_seconds + interference_seconds;
    let antenna_capacity_seconds = v.ground_antennas * 44;
    let sent_seconds = transmit_seconds.min(antenna_capacity_seconds);
    let queued_seconds = (transmit_seconds - antenna_capacity_seconds).max(0);
    let transmission_windows = transmit_seconds / 25;
    ResponseOutput {
        uplink_packet_total: v.science_packets + v.navigation_packets,
        science_transmit_seconds,
        navigation_transmit_seconds,
        interference_seconds,
        transmit_seconds,
        antenna_capacity_seconds,
        sent_seconds,
        queued_seconds,
        transmission_windows,
        uplink_score: sent_seconds + queued_seconds * 7 + transmission_windows * 12,
        uplink_mode: if queued_seconds == 0 { "synchronized" } else if v.solar_interference { "solar_queue" } else { "routine_queue" }.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_satellite_uplink_score(a: i64, b: i64, c: i64, d: i32) -> i64 {
    score(a, b, c, d != 0)
}

