const wildfireMissionScore = (scoutDrones, cargoDrones, launchPads, nightMission) => {
  const scoutFlightMinutes = scoutDrones * 13;
  const cargoFlightMinutes = cargoDrones * 21;
  const nightSetupMinutes = nightMission ? launchPads * 8 : 0;
  const missionLoadMinutes = scoutFlightMinutes + cargoFlightMinutes + nightSetupMinutes;
  const launchCapacityMinutes = launchPads * 50;
  const completedFlightMinutes = Math.min(missionLoadMinutes, launchCapacityMinutes);
  const delayedFlightMinutes = Math.max(missionLoadMinutes - launchCapacityMinutes, 0);
  const flightWaves = Math.floor(missionLoadMinutes / 40);
  return BigInt(completedFlightMinutes + delayedFlightMinutes * 6 + flightWaves * 9);
};
export async function loadParley() { return { wildfire_mission_score: wildfireMissionScore }; }

