import { Hono } from "hono";
import { z } from "zod";
import { handle } from "./logic.js";

declare const process: { env: Record<string, string | undefined> };
const maxBodyBytes = 16_384;
const schema = z.object({ passenger_groups:z.number().int().nonnegative(), supply_crates:z.number().int().nonnegative(), gondola_cabins:z.number().int().nonnegative(), express_service:z.boolean() }).strict();
const response = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });
const error = (code: string, status: number, detail: string) => response({ error: code, detail }, status);
const app = new Hono();

app.get("/status/alpine-gondola-ready", () => response({ service: "Alpine Gondola", ready: true }));
app.post("/api/v7/alpine-gondola", async (context) => {
  const mediaType = (context.req.header("content-type") ?? "").split(";", 1)[0]!.trim().toLowerCase();
  if (mediaType !== "application/json" && !mediaType.endsWith("+json")) return error("json_content_type_required", 415, "expected application/json");
