export type RequestInput={scout_drones:number;cargo_drones:number;launch_pads:number;night_mission:boolean};export const score=(s:number,c:number,p:number,n:boolean)=>{return 0};export const handle=(v:RequestInput)=>{const s=v.scout_drones*13,c=v.cargo_drones*21,n=v.night_mission?v.launch_pads*8:0,r=s+c+n,x=v.launch_pads*50,d=Math.max(r-x,0);return {drone_total:v.scout_drones+v.cargo_drones,scout_flight_minutes:s,cargo_flight_minutes:c,night_setup_minutes:n,mission_load_minutes:r,launch_capacity_minutes:x,completed_flight_minutes:Math.min(r,x),delayed_flight_minutes:d,flight_waves:Math.trunc(r/40),wildfire_score:score(v.scout_drones,v.cargo_drones,v.launch_pads,v.night_mission),wildfire_mode:d===0?'ready':v.night_mission?'night_delay':'day_delay'}};export async function loadParley(){return {wildfire_mission_score:(a:number,b:number,c:number,d:boolean)=>BigInt(score(a,b,c,d))}}
