export type RequestInput = {
  science_packets: number;
  navigation_packets: number;
  ground_antennas: number;
  solar_interference: boolean;
};

export const score = (sciencePackets: number, navigationPackets: number, antennas: number, solarInterference: boolean) => {
  const scienceSeconds = sciencePackets * 6;
  const navigationSeconds = navigationPackets * 10;
  const interferenceSeconds = solarInterference ? antennas * 7 : 0;
  const transmitSeconds = scienceSeconds + navigationSeconds + interferenceSeconds;
  const capacitySeconds = antennas * 44;
  const sentSeconds = Math.min(transmitSeconds, capacitySeconds);
  const queuedSeconds = Math.max(transmitSeconds - capacitySeconds, 0);
  const transmissionWindows = Math.floor(transmitSeconds / 25);

  return sentSeconds + queuedSeconds * 7 + transmissionWindows * 12;
};

export const handle = (value: RequestInput) => {
  const scienceTransmitSeconds = value.science_packets * 6;
  const navigationTransmitSeconds = value.navigation_packets * 10;
  const interferenceSeconds = value.solar_interference ? value.ground_antennas * 7 : 0;
  const transmitSeconds = scienceTransmitSeconds + navigationTransmitSeconds + interferenceSeconds;
  const antennaCapacitySeconds = value.ground_antennas * 44;
  const sentSeconds = Math.min(transmitSeconds, antennaCapacitySeconds);
  const queuedSeconds = Math.max(transmitSeconds - antennaCapacitySeconds, 0);

  return {
    uplink_packet_total: value.science_packets + value.navigation_packets,
    science_transmit_seconds: scienceTransmitSeconds,
    navigation_transmit_seconds: navigationTransmitSeconds,
    interference_seconds: interferenceSeconds,
    transmit_seconds: transmitSeconds,
    antenna_capacity_seconds: antennaCapacitySeconds,
    sent_seconds: sentSeconds,
    queued_seconds: queuedSeconds,
    transmission_windows: Math.floor(transmitSeconds / 25),
    uplink_score: score(value.science_packets, value.navigation_packets, value.ground_antennas, value.solar_interference),
    uplink_mode: queuedSeconds === 0 ? "synchronized" : value.solar_interference ? "solar_queue" : "routine_queue",
  };
};

export async function loadParley() {
  return {
    satellite_uplink_score: (sciencePackets: number, navigationPackets: number, antennas: number, solarInterference: boolean) =>
      BigInt(score(sciencePackets, navigationPackets, antennas, solarInterference)),
  };
}

