import { serve } from "@hono/node-server";
import { serveStatic } from "@hono/node-server/serve-static";
import { Hono } from "hono";
import { z } from "zod";
import { handle } from "./logic.js";

declare const process: { env: Record<string, string | undefined> };
const maxBodyBytes = 16_384;
const schema = z.object({ science_packets:z.number().int().nonnegative(), navigation_packets:z.number().int().nonnegative(), ground_antennas:z.number().int().nonnegative(), solar_interference:z.boolean() }).strict();
const response = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });
const error = (code: string, status: number, detail: string) => response({ error: code, detail }, status);
const app = new Hono();

app.get("/status/satellite-uplink-ready", () => response({ service: "Satellite Uplink", ready: true }));
app.post("/api/v7/satellite-uplink", async (context) => {
  const mediaType = (context.req.header("content-type") ?? "").split(";", 1)[0]!.trim().toLowerCase();
