const satelliteUplinkScore = (sciencePackets, navigationPackets, groundAntennas, solarInterference) => {
  const transmitSeconds = sciencePackets * 6 + navigationPackets * 10
    + (solarInterference ? groundAntennas * 7 : 0);
  const antennaCapacitySeconds = groundAntennas * 44;
  const sentSeconds = Math.min(transmitSeconds, antennaCapacitySeconds);
  const queuedSeconds = Math.max(transmitSeconds - antennaCapacitySeconds, 0);
  return sentSeconds + queuedSeconds * 7 + Math.floor(transmitSeconds / 25) * 12;
};
export async function loadParley() { return { satellite_uplink_score: satelliteUplinkScore }; }

