export type RequestInput = {
  scout_drones: number;
  cargo_drones: number;
  launch_pads: number;
  night_mission: boolean;
};

export const score = (
  scoutDrones: number,
  cargoDrones: number,
  launchPads: number,
  nightMission: boolean,
) => {
  const missionLoad =
    scoutDrones * 13 +
    cargoDrones * 21 +
    (nightMission ? launchPads * 8 : 0);
  const capacity = launchPads * 50;
  const completed = Math.min(missionLoad, capacity);
  const delayed = Math.max(missionLoad - capacity, 0);
  const waves = Math.floor(missionLoad / 40);

  return completed + delayed * 6 + waves * 9;
};

export const handle = (value: RequestInput) => {
  const scoutFlightMinutes = value.scout_drones * 13;
  const cargoFlightMinutes = value.cargo_drones * 21;
  const nightSetupMinutes = value.night_mission ? value.launch_pads * 8 : 0;
  const missionLoadMinutes =
    scoutFlightMinutes + cargoFlightMinutes + nightSetupMinutes;
  const launchCapacityMinutes = value.launch_pads * 50;
  const delayedFlightMinutes = Math.max(
    missionLoadMinutes - launchCapacityMinutes,
    0,
  );

  return {
    drone_total: value.scout_drones + value.cargo_drones,
    scout_flight_minutes: scoutFlightMinutes,
    cargo_flight_minutes: cargoFlightMinutes,
    night_setup_minutes: nightSetupMinutes,
    mission_load_minutes: missionLoadMinutes,
    launch_capacity_minutes: launchCapacityMinutes,
    completed_flight_minutes: Math.min(
      missionLoadMinutes,
      launchCapacityMinutes,
    ),
    delayed_flight_minutes: delayedFlightMinutes,
    flight_waves: Math.floor(missionLoadMinutes / 40),
    wildfire_score: score(
      value.scout_drones,
      value.cargo_drones,
      value.launch_pads,
      value.night_mission,
    ),
    wildfire_mode:
      delayedFlightMinutes === 0
        ? "ready"
        : value.night_mission
          ? "night_delay"
          : "day_delay",
  };
};

export async function loadParley() {
  return { wildfire_mission_score: score };
}

